  +import {
  +  component$,
  +  useStore,
  +  useVisibleTask$,
  +  type PropFunction,
  +} from "@builder.io/qwik";
  +import type { Persona } from "../../types";
  +import { loadPersonasFromIdb } from "../../utils/idb";
  +import { PERSONAS as DEFAULT_PERSONAS } from "../../utils/personas";
  +import type { SelectionActionState } from "./editor-state";
  +
  +interface SelectionActionsProps {
  +  selection: SelectionActionState | null;
  +  disabled?: boolean;
  +  onGetSources$: PropFunction<() => void>;
  +  onAddMargin$: PropFunction<() => void>;
  +  onSendToPersona$: PropFunction<
  +    (personaId: string, personaName: string) => void
  +  >;
  +  onClose$: PropFunction<() => void>;
  +}
  +
  +interface SelectionActionsStore {
  +  personas: Persona[];
  +  personaOpen: boolean;
  +}
  +
  +/** A compact, manuscript-anchored action card for a selected passage. */
  +export const SelectionActions = component$<SelectionActionsProps>((props) => {
  +  const store = useStore<SelectionActionsStore>({
  +    personas: DEFAULT_PERSONAS,
  +    personaOpen: false,
  +  });
  +
  +  // eslint-disable-next-line qwik/no-use-visible-task
  +  useVisibleTask$(async () => {
  +    const custom = await loadPersonasFromIdb();
  +    if (custom?.length) store.personas = custom;
  +  });
  +
  +  const selection = props.selection;
  +  if (!selection) return null;
  +
  +  return (
  +    <div
  +      class={["selection-actions", `selection-actions--${selection.placement}`]}
  +      style={{ left: `${selection.x}px`, top: `${selection.y}px` }}
  +      role="toolbar"
  +      aria-label={`Actions for “${selection.text.slice(0, 70)}”`}
  +      onMouseDown$={(event) => {
  +        // Keep the Tiptap selection intact while a card control receives focus.
  +        if (!(event.target instanceof HTMLTextAreaElement))
  +          event.preventDefault();
  +      }}
  +    >
  +      <div class="selection-actions__quote" title={selection.text}>
  +        “{selection.text.slice(0, 82)}
  +        {selection.text.length > 82 ? "…" : ""}”
  +      </div>
  +      <div class="selection-actions__row">
  +        <button
  +          type="button"
  +          onClick$={props.onGetSources$}
  +          disabled={props.disabled}
  +        >
  +          Get sources
  +        </button>
  +        <button
  +          type="button"
  +          onClick$={props.onAddMargin$}
  +          disabled={props.disabled}
  +        >
  +          Add margin
  +        </button>
  +        <button
  +          type="button"
  +          aria-haspopup="menu"
  +          aria-expanded={store.personaOpen}
  +          onClick$={() => {
  +            store.personaOpen = !store.personaOpen;
  +          }}
  +          disabled={props.disabled}
  +        >
  +          Send to persona
  +        </button>
  +        <button
  +          type="button"
  +          class="selection-actions__close"
  +          onClick$={props.onClose$}
  +          aria-label="Dismiss selection actions"
  +        >
  +          ×
  +        </button>
  +      </div>
  +      {selection.error && (
  +        <p class="selection-actions__error" role="status">
  +          {selection.error}
  +        </p>
  +      )}
  +      {store.personaOpen && (
  +        <div class="selection-actions__personas" role="menu">
  +          <p>Request a reading from</p>
  +          {store.personas.map((persona) => (
  +            <button
  +              key={persona.id}
  +              type="button"
  +              role="menuitem"
  +              onClick$={() => {
  +                store.personaOpen = false;
  +                props.onSendToPersona$(persona.id, persona.name);
  +              }}
  +            >
  +              <span
  +                class="selection-actions__persona-mark"
  +                style={{ color: persona.color }}
  +                aria-hidden="true"
  +              >
  +                {persona.icon}
  +              </span>
  +              <span>
  +                <strong>{persona.name}</strong>
  +                <small>{persona.role}</small>
  +              </span>
  +            </button>
  +          ))}
  +        </div>
  +      )}
  +    </div>
  +  );
  +});

  diff --git a/src/components/editorial-board/editorial-board-overlay.tsx b/src/components/editorial-board/editorial-board-overlay.tsx
  new file mode 100644
  index 0000000..b03350a
  --- /dev/null
  +++ b/src/components/editorial-board/editorial-board-overlay.tsx
  @@ -0,0 +1,232 @@
  +import {
  +  $,
  +  Slot,
  +  component$,
  +  useStore,
  +  type PropFunction,
  +} from "@builder.io/qwik";
  +import { steerBackgroundResearch } from "../../utils/background-research";
  +import type { ActivityCounts, PanelId } from "../../utils/panel-activity";
  +
  +export interface EditorialBoardTab {
  +  id: PanelId;
  +  numeral: string;
  +  label: string;
  +  kicker: string;
  +  accent: string;
  +}
  +
  +interface EditorialBoardOverlayProps {
  +  open: boolean;
  +  activeContext: PanelId;
  +  activity: ActivityCounts;
  +  tabs: EditorialBoardTab[];
  +  onContext$: PropFunction<(panel: PanelId) => void>;
  +  onClose$: PropFunction<() => void>;
  +}
  +
  +interface OverlayStore {
  +  steeringCollapsed: boolean;
  +  boardCollapsed: boolean;
  +  steeringDraft: string;
  +  steeringBusy: boolean;
  +  steeringNotice: string | null;
  +  steeringError: string | null;
  +}
  +
  +/**
  + * The Editorial Board as furniture on the manuscript rather than another
  + * application rail. Its children remain mounted while closed so searches,
  + * streams, replies, and error recovery continue without losing state.
  + */
  +export const EditorialBoardOverlay = component$<EditorialBoardOverlayProps>(
  +  (props) => {
  +    const store = useStore<OverlayStore>({
  +      steeringCollapsed: false,
  +      boardCollapsed: false,
  +      steeringDraft: "",
  +      steeringBusy: false,
  +      steeringNotice: null,
  +      steeringError: null,
  +    });
  +
  +    const submitSteering = $(async () => {
  +      const direction = store.steeringDraft.trim();
  +      if (!direction || store.steeringBusy) return;
  +      store.steeringBusy = true;
  +      store.steeringError = null;
  +      store.steeringNotice = null;
  +      const result = await steerBackgroundResearch(direction);
  +      store.steeringBusy = false;
  +      if (!result.ok) {
  +        store.steeringError =
  +          result.message ?? "The Apparatus could not start.";
  +        return;
  +      }
  +      store.steeringNotice = "Direction added to the next research pass.";
  +      store.steeringDraft = "";
  +    });
  +
  +    const activeTab =
  +      props.tabs.find((tab) => tab.id === props.activeContext) ?? props.tabs[0];
  +
  +    return (
  +      <aside
  +        class={[
  +          "editorial-overlay",
  +          { "editorial-overlay--closed": !props.open },
  +        ]}
  +        aria-label="The Editorial Board"
  +        aria-hidden={!props.open}
  +      >
  +        <div class="editorial-overlay__topline">
  +          <div>
  +            <p class="dept-label">The Editorial Board</p>
  +            <p class="editorial-overlay__context-line">
  +              {activeTab.numeral} · {activeTab.label} · {activeTab.kicker}
  +            </p>
  +          </div>
  +          <button
  +            type="button"
  +            class="editorial-overlay__close focus-ring"
  +            onClick$={props.onClose$}
  +            aria-label="Close the Editorial Board"
  +          >
  +            ×
  +          </button>
  +        </div>
  +
  +        {props.activeContext === "citations" && (
  +          <section class="editorial-overlay-card editorial-steering-card">
  +            <header class="editorial-overlay-card__head">
  +              <div>
  +                <p class="dept-label">Steering</p>
  +                <h2>Direct the search</h2>
  +              </div>
  +              <button
  +                type="button"
  +                class="editorial-card-collapse focus-ring"
  +                onClick$={() => {
  +                  store.steeringCollapsed = !store.steeringCollapsed;
  +                }}
  +                aria-expanded={!store.steeringCollapsed}
  +                aria-label={
  +                  store.steeringCollapsed
  +                    ? "Expand research steering"
  +                    : "Collapse research steering"
  +                }
  +              >
  +                {store.steeringCollapsed ? "+" : "−"}
  +              </button>
  +            </header>
  +            {!store.steeringCollapsed && (
  +              <form
  +                class="editorial-steering-card__body"
  +                preventdefault:submit
  +                onSubmit$={submitSteering}
  +              >
  +                <label for="apparatus-steering">
  +                  Tell the Apparatus what evidence matters, where to look, or
  +                  which source should be treated as original.
  +                </label>
  +                <div class="editorial-steering-card__input-row">
  +                  <textarea
  +                    id="apparatus-steering"
  +                    rows={2}
  +                    value={store.steeringDraft}
  +                    placeholder="Prefer primary sources; trace this quotation to its first publication…"
  +                    onInput$={(_, element) => {
  +                      store.steeringDraft = element.value;
  +                      store.steeringError = null;
  +                      store.steeringNotice = null;
  +                    }}
  +                  />
  +                  <button
  +                    type="submit"
  +                    class="btn-press"
  +                    disabled={!store.steeringDraft.trim() || store.steeringBusy}
  +                  >
  +                    {store.steeringBusy ? "Directing…" : "Steer"}
  +                  </button>
  +                </div>
  +                {(store.steeringError || store.steeringNotice) && (
  +                  <p
  +                    class={
  +                      store.steeringError
  +                        ? "editorial-steering-card__error"
  +                        : "editorial-steering-card__notice"
  +                    }
  +                    role="status"
  +                  >
  +                    {store.steeringError ?? store.steeringNotice}
  +                  </p>
  +                )}
  +              </form>
  +            )}
  +          </section>
  +        )}
  +
  +        <section
  +          class="editorial-overlay-card editorial-board-card"
  +          style={{ "--board-accent": activeTab.accent }}
  +        >
  +          <header class="editorial-board-card__head">
  +            <nav class="editorial-board-contexts" aria-label="Board context">
  +              {props.tabs.map((tab) => {
  +                const active = tab.id === props.activeContext;
  +                const unread = props.activity[tab.id] ?? 0;
  +                return (
  +                  <button
  +                    key={tab.id}
  +                    type="button"
  +                    class={[
  +                      "editorial-board-context focus-ring",
  +                      { "editorial-board-context--active": active },
  +                    ]}
  +                    style={{ "--context-accent": tab.accent }}
  +                    onClick$={() => props.onContext$(tab.id)}
  +                    aria-pressed={active}
  +                    aria-label={
  +                      unread > 0 ? `${tab.label} — ${unread} new` : tab.label
  +                    }
  +                  >
  +                    <span aria-hidden="true">{tab.numeral}</span>
  +                    <strong>{tab.label}</strong>
  +                    {unread > 0 && !active && (
  +                      <small aria-hidden="true">
  +                        {unread > 9 ? "9+" : unread}
  +                      </small>
  +                    )}
  +                  </button>
  +                );
  +              })}
  +            </nav>
  +            <button
  +              type="button"
  +              class="editorial-card-collapse focus-ring"
  +              onClick$={() => {
  +                store.boardCollapsed = !store.boardCollapsed;
  +              }}
  +              aria-expanded={!store.boardCollapsed}
  +              aria-label={
  +                store.boardCollapsed
  +                  ? `Expand ${activeTab.label}`
  +                  : `Collapse ${activeTab.label}`
  +              }
  +            >
  +              {store.boardCollapsed ? "+" : "−"}
  +            </button>
  +          </header>
  +          <div
  +            class={[
  +              "board-panel editorial-board-card__body",
  +              { hidden: store.boardCollapsed },
  +            ]}
  +          >
  +            <Slot />
  +          </div>
  +        </section>
  +      </aside>
  +    );
  +  },
  +);

