          store.noteText = "";
          store.noteInputKind = null;
          break;
        }

        case "insertMermaid": {
          if (store.mermaidSource.trim()) {
            chain
              .setMermaidDiagram({ source: store.mermaidSource.trim() })
              .run();
            store.mermaidSource = "";
            store.showMermaidInput = false;
          }
          break;
